#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int to;
    int next;
} Edge;

int head[200005];
Edge edges[800005];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int comp[200005];
int comp_size = 0;
bool visited[200005];
bool is_neighbor[200005];

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    int *queue = (int *)malloc((n + 5) * sizeof(int));

    for (int i = 1; i <= n; i++) {
        if (!visited[i]) {
            int q_head = 0, q_tail = 0;
            queue[q_tail++] = i;
            visited[i] = true;

            comp_size = 0;
            long long edge_sum = 0;

            while (q_head < q_tail) {
                int u = queue[q_head++];
                comp[comp_size++] = u;

                int deg = 0;
                for (int e = head[u]; e != -1; e = edges[e].next) {
                    deg++;
                    int v = edges[e].to;
                    if (!visited[v]) {
                        visited[v] = true;
                        queue[q_tail++] = v;
                    }
                }
                edge_sum += deg;
            }

            long long k = comp_size;
            if (edge_sum < k * (k - 1)) {
                // This component is not a clique
                int chosen_u = -1;
                for (int j = 0; j < comp_size; j++) {
                    int u = comp[j];
                    int deg = 0;
                    for (int e = head[u]; e != -1; e = edges[e].next) {
                        deg++;
                    }
                    if (deg < k - 1) {
                        chosen_u = u;
                        break;
                    }
                }

                // Mark all neighbors of chosen_u
                for (int e = head[chosen_u]; e != -1; e = edges[e].next) {
                    is_neighbor[edges[e].to] = true;
                }
                is_neighbor[chosen_u] = true;

                // Find a vertex in the same component not marked
                for (int j = 0; j < comp_size; j++) {
                    int v = comp[j];
                    if (!is_neighbor[v]) {
                        printf("%d %d\n", chosen_u, v);
                        free(queue);
                        return 0;
                    }
                }
            }
        }
    }

    printf("-1\n");
    free(queue);
    return 0;
}
